(8, 'Fabio Silva', 'fabio.silva@lumminin.com.br', NULL, '$2y$10$FGncVFPVq.znH2qoiC36uOA.blaoJQ3gZmvXVSQFl0ucy4GCa6rme', NULL, 'Habilitado', 1, '2026-08-13 14:57:54', '2026-08-13 14:57:54');
INSERT INTO `vagas` (`id`, `titulo`, `uf`, `cidade`, `descricao`, `area`, `nivel`, `escolaridade`, `tempo_experiencia`, `tipo_contrato`, `jornada`, `necessidade_especial`, `status`, `slug`, `created_at`, `updated_at`) VALUES
(1, 'Programa DESENVOLVER', 'PE', 'Recife', '<p style=\"text-align: justify; \">Olá pessoas, tudo bem?</p><p style=\"text-align: justify; \"><br></p><p style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Num mundo competitivo em constantes evoluções nossa proposta de VALOR é apoiar o profissional a encontrar equilibrio pessoal e profissional, tendo&nbsp;</span><span style=\"font-size: 1rem;\">como filosofia a entrega, transparência e compromisso.&nbsp;</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Nossa MENTORIA visa desenvolver e fortalecer competências utilizando metodologia que reúne ferramentas de coaching, SWOT, psicologia positiva e jogos direcionados a tomada de decisão, proporcionando insights que promovem a automotivação e autoconhecimento visando o desenvolvimento de potenciais e oportunidades de para o profissional de diversas áreas, na sua posição de liderança e gestão.&nbsp;</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Sessões on line. Vem com a gente?!</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Inscrições estão abertas para o programa, para agendamento da triagem no link:&nbsp;</span><a href=\"https://forms.gle/GSPFnoWTZXVugPvw6\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); font-size: 1rem;\">https://forms.gle/GSPFnoWTZXVugPvw6</a></p>', 'recursos-humanos', 'consultor', NULL, NULL, NULL, NULL, NULL, 'habilitada', '1-programa-desenvolver', '2023-08-23 00:13:30', '2024-07-23 18:14:05'),
(2, 'Supervisor de Loja', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de vendas no varejo e prestação de serviços em Construção Civil. </p><p><br></p><p>Para essa posição buscamos profissional responsável pelo planejamento, mapeamento e supervisão/ gestão dos processos e&nbsp; pessoas, visando implementação de políticas,&nbsp; acompanhamento de performance, indicadores. Necessário vivência no cargo,&nbsp; acompanhamento de processos e indicadores de performance. Habilidades com informática, sistemas de gestão, excel é preferencial.&nbsp; &nbsp;&nbsp;</p><p>Ensino superior completo em administração, negócios, logística e afins, ou correlatas a engenharias será preferencial,&nbsp;</p><p>Habilidades com informática, sistemas de gestão, excel.&nbsp;</p><p>Empresa oferece salário e benefícios compatíveis com mercado, para vaga presencial em Recife - PE.</p>', 'logistica', 'supervisor', 'Ensino superior', NULL, NULL, NULL, NULL, 'desabilitada', '2-supervisor-de-loja', '2023-08-23 14:43:37', '2024-04-26 13:21:41'),
(3, 'Vendedor', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de outsourcing de impressão. </p><p>\r\n\r\nPara esse perfil é necessário profissional com vivência na área de vendas B2b e habilidade com informática básica, preferencialmente CRM, indicadores de vendas e sistemas de gestão.</p><p> </p><p>Ensino superior completo ou cursando. </p><p>Habilidades de relacionamento, comunicação interpessoal e negociação são preferenciais.&nbsp;&nbsp;</p><p><br></p><p> Salário, vale transporte, assistência médica e ticket refeição.&nbsp;</p>', 'comercial', 'analista', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '3-vendedor', '2023-08-23 18:20:26', '2024-01-29 17:42:50'),
(4, 'Consultor Comercial', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de prestação de serviços em Engenharia.</p><p><br></p><p> </p><p>Para essa vaga, buscamos pessoa com formação superior cursando ou completa em negócios, administração ou afins.&nbsp;<span style=\"font-size: 1rem;\">Necessário ter vivência em vendas de serviços, preferencialmente B2b. Além de h</span><span style=\"font-size: 1rem;\">abilidades com informática, CRM, indicadores de vendas e negociação.&nbsp;</span></p><p><br></p><p> A empresa oferece salários e benefícios compatíveis com mercado.&nbsp;</p>', 'comercial', 'analista', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '4-consultor-comercial', '2023-08-23 19:03:46', '2024-03-13 15:01:29'),
(5, 'Assistente Administrativo Financeiro', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de prestação de serviços em Engenharia.</p><p><br></p><p></p><p>Para essa vaga, buscamos pessoa com formação superior cursando ou completa em negócios, administração ou afins. É n<span style=\"font-size: 1rem;\">ecessário ter vivência de estágio ou empregos na área de finanças, com controles, planilhas, relatórios e acompanhamentos. Ter h</span><span style=\"font-size: 1rem;\">abilidades com informática e sistemas será diferencial.&nbsp;</span></p><p>A empresa oferece salários e benefícios compatíveis com mercado.&nbsp;</p><p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;mso-fareast-font-family:SimSun;\r\nmso-bidi-font-family:\'Times New Roman\';\"></span></p><p>&nbsp;&nbsp; </p>', 'administrativo', 'assistente', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '5-assistente-administrativo-financeiro', '2023-08-23 21:02:04', '2024-01-03 20:47:13'),
(6, 'Estagiário(a) de RH', 'PE', 'Recife', '<p dir=\"ltr\" style=\"line-height:1.38;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;padding:0pt 0pt 22pt 0pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\">Nosso cliente é empresa de consultoria de gestão de pessoas que atua hibridamente com projetos de seleção, clima, diagnóstico, desenvolvimento e cultura organizacional. </span></p><p dir=\"ltr\" style=\"line-height:1.38;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;padding:0pt 0pt 22pt 0pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\">Para essa vaga, buscamos pessoa cursando superior em gestão de recursos humanos, administração, psicologia ou afins,  para estagiar no modelo híbrido com a</span><span style=\"background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); vertical-align: baseline;\">tendimento, abordagem e agendamento de candidatos, além de t</span><span style=\"color: rgb(29, 62, 102); font-family: &quot;Source Sans Pro&quot;; font-size: 14.6667px; white-space: pre;\">riagem de currículos, confecção de formulários,  participações em seleções, treinamentos, pesquisas nas visitas a clientes. </span></p><p dir=\"ltr\" style=\"line-height:1.38;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;padding:0pt 0pt 22pt 0pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\">Necessário ter habilidade de comunicação, trabalho em equipe, proatividade, dinamismo e interesse em aprender</span><span style=\"font-size: 12pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(55, 65, 81); background-color: transparent; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\">.</span><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap;\"> </span></p><p dir=\"ltr\" style=\"line-height:1.38;text-align: justify;background-color:#ffffff;margin-top:0pt;margin-bottom:0pt;padding:0pt 0pt 22pt 0pt;\"><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; background-color: transparent; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); vertical-align: baseline;\">Necessário habilidade com </span><span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; background-color: transparent; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); vertical-align: baseline;\">informática, para o manuseio de plataformas de gestão de compartilhamento de dados online pelo drive e métodos ágeis.</span></p>', 'recursos-humanos', 'estagiario', 'Ensino superior', 'Menos de 1 ano', 'estagio', 'Parcial Tarde', NULL, 'desabilitada', '6-estagiarioa-de-rh', '2023-12-06 17:29:19', '2024-10-08 13:21:52'),
(7, 'Estagiário Administrativo', 'PE', 'Recife', '<p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Industria localizada no CURADO, busca estagiário para aprendizado e desenvolvimento, para estágio presencial. segunda a sexta das  8 às 12h/ 13 às 15h., no seguinte perfil: </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Cursando superior em administração, negócios, economia ou afins,  a partir do 3º período, <br></span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Necessário ter habilidade de comunicação, trabalho em equipe, proatividade, dinamismo e interesse em aprender</span><span style=\"font-size: 12pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(55, 65, 81); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">.</span><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"background-color: transparent; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Habilidade em informática básica (como word, excel e power point), plataformas de compartilhamento de dados (como meet, drive , etc) e / ou ferramentas ágeis. </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><font color=\"#1d3e66\" face=\"Source Sans Pro\"><span style=\"font-size: 14.6667px; white-space-collapse: preserve;\">Idioma Espanhol (intermediário a fluente).</span></font></p><p><span id=\"docs-internal-guid-d8170c60-7fff-f9ed-4820-61105e271176\"></span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 22pt; line-height: 1.38; text-align: justify;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Empresa oferece bolsa de estágio compatível com o mercado, refeitório, vale transporte e oportunidade de crescimento. </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 22pt; line-height: 1.38; text-align: justify;\"><br></p>', 'administrativo', 'estagiario', 'Ensino superior', 'Sem experiência', 'estagio', 'Parcial Manhã', NULL, 'desabilitada', '7-estagiario-administrativo', '2024-01-22 12:19:27', '2024-03-05 16:21:33'),
(8, 'Vendedor Externo', 'PE', 'Recife', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Nosso cliente é uma industria de soluções tecnológicas.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Para esse perfil é necessário profissional com vivência na área de vendas B2B e habilidade com informática básica, preferencialmente CRM, indicadores de vendas e sistemas de gestão.</span></p><p></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Ensino superior completo ou cursando, em administração, gestão comercial, negócios ou afins.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Habilidades de relacionamento, comunicação interpessoal e negociação são preferenciais.&nbsp;&nbsp;</span></p><p><br></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Oferecemos salário compatível com mercado,&nbsp; vale transporte e refeição no local.&nbsp;</span></p>', 'comercial', 'analista', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '8-vendedor-externo', '2024-01-22 12:34:17', '2024-07-10 11:05:27'),
(9, 'Analista de Controladoria', 'PE', 'Recife', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Nosso cliente é uma industria de soluções tecnológicas.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Para esse perfil é necessário profissional com vivência na área de Controladoria, preferencialmente em indústria&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Source Sans Pro&quot;;\">com custos, relatórios gerenciais, análise de resultados, balanços e demonstrativos contábeis, além de análise em orçamentos e despesas,&nbsp; e noções fiscais.&nbsp;</span><span style=\"font-size: 1rem; font-family: &quot;Source Sans Pro&quot;;\">&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Formação superior completa/ cursando em Administração, contábeis, economia e afins.&nbsp;</span></p><p><span style=\"font-size: 1rem; font-family: &quot;Source Sans Pro&quot;;\">Habilidade com ferramentas de informática e tecnologias, ERP, excel e outros.</span><br></p><p>Vivência com indicadores e análise de dados,&nbsp;</p><p>Espírito de time, boa comunicação, iniciativa, abertura ao aprendizado e adaptação às mudanças,&nbsp;</p><p>Disponibilidade para atuar presencialmente no curado.&nbsp;</p><p><br></p><p>Empresa oferece salário, VT e refeição no local.</p>', 'contabil', 'analista', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '9-analista-de-controladoria', '2024-01-23 06:17:59', '2024-02-23 12:15:27'),
(10, 'Líder de costura', 'PE', 'Recife', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Nosso cliente é uma marca/ confecção de Moda, com rede própria e e-commerce.&nbsp;</span><br></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Para esse perfil é necessário profissional com vivência na área de produção, com gestão de pessoas e processos produtivos. O diferencial será ter vivência em confecção e costura industrial.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Ensino técnico/ superior completo ou cursando, em administração, gestão industrial, técnico em vestuário ou afins.&nbsp;</span><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\"><br></span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Atuar na liderança de equipes de produção e costura de máquinas: reta, overloque, galoneira, eletrônica, travete, ponto corrente e prespontadeira.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Habilidades de relacionamento interpessoal, comunicação, planejamento e gestão são preferenciais.&nbsp;&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Atuar na&nbsp;</span></p><p><br></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Oferecemos salário compatível com mercado,&nbsp; vale transporte, assistência médica.&nbsp;</span></p>', 'industrial', 'encarregado', 'Nível Técnico', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '10-lider-de-costura', '2024-03-05 16:29:17', '2024-06-03 20:30:09'),
(11, 'Costureiro(a)', 'PE', 'Recife', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Nosso cliente é um confecção de Moda.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Para esse perfil é necessário profissional com estágio ou vivência na área de produção de costura, com máquinas, reta, overloque, galoneira, entre outras máquinas industriais.&nbsp;</span></p><p></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Curso profissionalizante ou técnico em vestuário, costura e afins.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Disponibilidade para o trabalho em equipe, boa comunicação, foco em resultados e atenção concentrada.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\"><br></span></p><p><font face=\"Source Sans Pro\">O horário de trabalho de segunda a sexta! E a&nbsp;</font><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">empresa oferece salário compatível com mercado,&nbsp; vale transporte, ticket, assistência médica.&nbsp;</span></p>', 'industrial', 'operacional', 'Ensino fundamental (1º grau)', 'Menos de 1 ano', 'efetivo', 'Período Integral', NULL, 'desabilitada', '11-costureiroa', '2024-03-05 18:47:18', '2024-07-18 20:03:35'),
(12, 'Analista de Marketing', 'PE', 'Recife', '<p><span style=\"font-size: 1rem;\">Nosso cliente é uma industria de soluções tecnológicas.</span><br></p><p><span style=\"font-size: 1rem;\">Para esse perfil é necessário profissional com vivência na área de Marketing, para atuar com estratégias de marketing no acompanhamento de agência, redes sociais, planejamento de feiras, eventos, manutenção de catálogos,&nbsp; campanhas, mídias, contratação de fornecedores, acompanhamento de métricas e indicadores da área, alinhamento com estratégias comerciais entre outras rotinas da área de marketing.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Formação superior cursando ou completa em Administração, Marketing, Publicidade ou afins.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Habilidade com ferramentas de informática, sistemas, apresentações, planilhas de controle e análise de dados para suporte as decisões.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Comunicação, espírito de equipe, iniciativa, abertura ao aprendizado e adaptação às mudanças.</span></p><p><span style=\"font-size: 1rem;\">Vivências de estágio/ emprego na área e disposição para aprendizado e crescimento.&nbsp;</span><br></p><p>Disponibilidade e interesse para atuar em industria no Curado, presencial.&nbsp;</p><p><br></p><p>Empresa oferece salário, VT e refeição no local.</p>', 'marketing', 'analista', 'Ensino superior', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '12-analista-de-marketing', '2024-04-11 14:58:15', '2024-06-13 13:31:13'),
(13, 'Coordenador de RH', 'PE', 'Jaboatão dos Guararapes', '<p>Nosso cliente é uma distribuidor de atuação em Pernambuco e Paraiba.&nbsp;</p><p>Disponibilidade para atuação 100% presencial em Jaboatão dos Guararapes.&nbsp;</p><p>Para essa posição, buscamos profissional com disponibilidade de atuação Pessoa Jurídica, com vivência na área de RH em todos os subsistemas, para implantação e reestruturação de projetos e processos, atuando na performance e desempenho das pessoas, visando alcance de melhores resultados.&nbsp;</p><p>Formação Superior completa em Administração, Psicologia ou afins.</p><p>Habilidades com ferramentas de informáticas, indicadores, apresentações e análise de dados para tomada de decisão.&nbsp;</p><p>Proatividade, comunicação, relacionamento interpessoal e político, resiliêencia, planejamento, visão sistêmica, gestão de pessoas e processos.</p><p>Pós graduação será diferencial.&nbsp;</p><p><br></p><p><br></p>', 'recursos-humanos', 'gerente', 'Pós-graduação (especialização/ MBA)', 'Entre 3 e 5 anos', 'prestador-de-servicos', 'Período Integral', NULL, 'desabilitada', '13-coordenador-de-rh', '2024-04-12 19:18:08', '2024-05-10 17:10:26'),
(14, 'Técnico em Informática', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de prestação de serviços em tecnologia, atuando com outsousing de impressão.&nbsp;</p><p>Para essa posição buscamos profissional técnico, com habilidades relacionais para atuar na prestação de serviço com visitas ao atendimento no cliente, com flexibilidade e adaptação as mudanças.&nbsp;</p><p>Formação: Técnico em informática, eletrônica e afins.&nbsp;</p><p>Habildades em montagem e desmontagem de equipametos de tecnologia:computadores, notebooks, impressoras. etc.&nbsp;<br></p><p>Conhecimentos em microinformática, hardware, redes de computadores com cabeamento e sem fio,&nbsp;</p><p>Proatividade, comunicação, relacionamento interpessoal, organização.&nbsp;</p>', 'informatica', 'operacional', 'Nível Técnico', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '14-tecnico-em-informatica', '2024-04-27 11:25:29', '2024-05-21 00:54:11'),
(15, 'Consultor comercial', 'PE', 'Ipojuca', '<p>Nosso cliente é uma empresa do segmento de moda, industria e lojas com&nbsp; vendas on line e off line.&nbsp;</p><p><span style=\"font-size: 1rem;\">Para esta posição buscamos profissional para atuar no formato consultor/ representação comercial no modelo Pessoa jurídica.&nbsp;</span></p><p><br></p><p>Formação: Administração, Marketing, negócios ou afins.&nbsp;</p><p>Habilidades com comunicação, negociação, captação de clientes,&nbsp;</p><p>Necessário vivência comercial externa, com planos de negócios, CRM, acompanhamento de estoques, campanhas e engajamento.&nbsp;</p><p>Atuação híbrida, no formato prestação de serviços (podendo ser MEI), com variável sobre os resultados de vendas e ajuda de custo.&nbsp;</p><p>Possuir veículo será diferencial para deslocamento e visita a cliente.</p>', 'comercial', 'consultor', 'Ensino superior', 'Entre 1 a 3 anos', 'prestador-de-servicos', 'Parcial Manhã', NULL, 'desabilitada', '15-consultor-comercial', '2024-04-27 11:31:03', '2024-08-22 16:45:11'),
(16, 'Técnico de segurança do Trabalho', 'PE', 'Moreno', '<p>Nosso cliente é uma consultoria de engenharia de medicina, saúde e segurança ocupacional que atende diversas empresas.&nbsp;</p><p>Para essa posição buscamos profissional com formação técnica completa em segurança do trabalho. Necessário experiência na área, industria e varejo será diferencial.&nbsp;</p><p>Habilidades em ferramentas de informática, drives, plataformas e gerenciamento de dados para apresentações.&nbsp;</p><p>habilidade em NR-11 / 33 e 35.</p><p><span style=\"font-size: 1rem;\">Modelo de trabalho 100% presencial</span><br></p>', 'seguranca-trabalho', 'analista', 'Nível Técnico', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '16-tecnico-de-seguranca-do-trabalho', '2024-05-21 01:02:16', '2024-06-03 12:39:13'),
(17, 'Estagiário COMEX', 'PE', 'Recife', '<p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"background-color: transparent; color: rgb(29, 62, 102); font-family: &quot;Source Sans Pro&quot;; font-size: 11pt; white-space-collapse: preserve;\">Nosso cliente é uma industria de soluções tecnológicas localizada no CURADO, que busca estagiário para aprendizado e desenvolvimento.</span><br></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Cursando superior em administração, negócios, logística ou afins,  a partir do 3º período, com interesse em áreas comercial e/ou logística. </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"background-color: transparent; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Necessário ter habilidade de comunicação, trabalho em equipe, proatividade, dinamismo e interesse no aprendizado contínuo. </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><span style=\"background-color: transparent; font-size: 11pt; font-family: &quot;Source Sans Pro&quot;; color: rgb(29, 62, 102); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">Habilidade em informática básica (como word, excel e power point), plataformas de compartilhamento de dados (trello, meet, drive , etc) e/ ou ferramentas ágeis. </span></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><font color=\"#1d3e66\" face=\"Source Sans Pro\"><span style=\"font-size: 14.6667px; white-space-collapse: preserve;\">Inglês será diferencial  para e-mail e documentos.</span></font></p><p dir=\"ltr\" style=\"margin-top: 0pt; margin-bottom: 0pt; line-height: 1.38; text-align: justify; padding: 0pt 0pt 22pt;\"><font color=\"#1d3e66\" face=\"Source Sans Pro\"><span style=\"font-size: 14.6667px; white-space-collapse: preserve;\">Estágio 100 % presencial. </span></font></p>', 'industrial', 'estagiario', 'Ensino superior', 'Sem experiência', 'estagio', NULL, NULL, 'desabilitada', '17-estagiario-comex', '2024-06-26 11:00:33', '2024-07-22 15:03:26'),
(18, 'Técnico de segurança do Trabalho', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de consultoria de engenharia em medicina, saúde e segurança ocupacional.</p><p>Para essa posição buscamos técnicco de segurança com formação completa, experiência de estágio ou emprego comprovada na área para atuar na RMR - região metropolitana do Recife.&nbsp;</p><p>Para essa vaga o Técnico atuará em clientes diferentes, é necessário iniciativa, proatividade e organização.&nbsp;</p><p>Habilidade em ferramentas de informática, drives, plataformas e arquivos para gerencimaento de informações com a matriz.&nbsp;</p><p>Habilidade nas NRs 11, 33 e 35 será diferencial.&nbsp;</p><p>Atuação 100% presencial, segunda a sexta 8 às 17h.&nbsp;</p>', 'seguranca-trabalho', 'analista', 'Nível Técnico', NULL, 'efetivo', 'Período Integral', NULL, 'desabilitada', '18-tecnico-de-seguranca-do-trabalho', '2024-07-10 11:04:27', '2024-10-08 13:16:17'),
(19, 'Técnico de segurança do Trabalho', 'PE', 'Bezerros', '<p>Nosso cliente é uma empresa de consultoria em engenharia de medicina, saúde e segurança ocupacional localizada em recife com expansão em Pernambuco, com matriz em Recife/ PE.</p><p>Para essa posição buscamos profissional com formação técnica em segurança do trabalho com&nbsp;<span style=\"font-size: 1rem;\">experiência comprovada de estágio e/ou emprego em industria e/ ou varejo.</span></p><p><span style=\"font-size: 1rem;\">Habilidades nas NRs 11, 33 e 35 será diferencial.&nbsp;</span></p><p>Habilidade em ferramentas de informática, drive, vídeos, plataformas para gerenciamento de dados remoto e comunicação com matriz.&nbsp;</p><p>Vaga 100% presencial. </p><p>Ter veículo será diferencial, e disponibilidade para visita a lojas em cidades da região em Bezerros, Gravatá, Caruaru e Santa cruz.&nbsp;</p><p>Empresa oferece salário e&nbsp; benefícios compatíveis com mercado.&nbsp;</p>', 'seguranca-trabalho', 'analista', 'Nível Técnico', 'Entre 1 a 3 anos', 'efetivo', 'Período Integral', NULL, 'desabilitada', '19-tecnico-de-seguranca-do-trabalho', '2024-07-10 11:53:47', '2024-08-27 14:48:10'),
(20, 'Auxiliar Administrativo', 'PE', 'Recife', '<p><font color=\"#003163\" face=\"-apple-system, system-ui, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Fira Sans, Ubuntu, Oxygen, Oxygen Sans, Cantarell, Droid Sans, Apple Color Emoji, Segoe UI Emoji, Segoe UI Emoji, Segoe UI Symbol, Lucida Grande, Helvetica, Arial, sans-serif\"><span style=\"font-size: 14px; white-space-collapse: preserve; font-family: &quot;Source Sans Pro&quot;;\">Nosso cliente é uma empresa de consultoria em soluções contábeis. E para essa posição, buscamos profissional com perfil:</span></font></p><p><span style=\"color: rgb(29, 62, 102); font-family: &quot;Source Sans Pro&quot;; font-size: 14px; white-space-collapse: preserve;\">Formação técnica em Administração ou contabilidade, cursando ou completa, \r\nHabilidade com sistemas, plataformas e pacote oficce, \r\nDisposição para aprendizado e atuação 100% presencial, \r\nExperiências com rotinas administrativas, controles, conferências, atualizações de dados em sistemas e atendimento ao cliente, \r\nHorário comercial, com salário e benefícios compatíveis com mercado. </span></p>', 'contabil', 'auxiliar', 'Nível Técnico', 'Menos de 1 ano', 'efetivo', 'Período Integral', NULL, 'desabilitada', '20-auxiliar-administrativo', '2024-08-26 17:34:42', '2025-08-22 12:35:00'),
(21, 'Analista de Logística', 'PB', 'Mamanguape', '<p>Nosso cliente é um grupo no segmento de varejo, com unidades em PE e PB.</p><p>Para esta posição buscamos profissional com formação técnica em logistica completa ou superior cursando/ completa em Administração, logística ou afins. Ter experiência na área de logistica estoque, armazém, levantamentos e distribuição de estoque,&nbsp; inventários, armazenagem e separação será diferencial.&nbsp;</p><p>Necessários boa comunicação, trabalho em equipe, organização e planejamento, habilidades com informática.&nbsp;</p><p>Disposição para aprendizado e crescimento, atuando com time de armazém, reportando a matriz.&nbsp;</p>', 'logistica', 'analista', 'Nível Técnico', 'Menos de 1 ano', 'efetivo', 'Período Integral', NULL, 'desabilitada', '21-analista-de-logistica', '2024-09-05 10:09:35', '2024-11-21 15:43:22'),
(22, 'Coordenador de Logística', 'PE', 'Olinda', '<p>Nosso cliente é um grupo no segmento de varejo.&nbsp;</p><p> Para esta posição buscamos profissional com formação superior completa em admistração, logística e afins. Ter pós-graduação será diferencial. </p><p>Vivência em gestão de pessoas e processos logíticos, preferencialmente armazenagem e distribuição,&nbsp;<span style=\"font-size: 1rem;\">controle e acuracidade de estoque,&nbsp;</span><span style=\"font-size: 1rem;\">planejamento e abastecimento logístico, orçamentos, inventários, logistica reversa, indicadores de performance.&nbsp;</span></p><p>Vivência em gestão de equipes, trabalho em equipe, foco em resultados, negociações com fornecedores, planejamento e visão de negócio.&nbsp;</p><p>Disponibiidade para viagens ocasionais, aprendizado e crescimento na empresa.&nbsp;</p>', 'logistica', 'coordenador', 'Ensino superior', NULL, 'efetivo', 'Período Integral', NULL, 'desabilitada', '22-coordenador-de-logistica', '2024-09-05 10:21:54', '2024-10-16 09:39:48'),
(23, 'Gerente Administrativo Financeiro', 'PE', 'Olinda', '<p>Nosso cliente é uma grupo de varejo. </p><p>E para esta posição, buscamos profissional com formação superior completa em administração, economia, contábeis ou afins.&nbsp;<span style=\"font-size: 1rem;\">Ter pós-graduação será diferencial.&nbsp;</span></p><p>Vivências em gestão de pessoas e processos administrativos financeiros: gestão, planejamento e controle de orçamentos, análises de finanças, custos, DRE, provisões e viabilidades financeiras. Além de fechamentos e apresentações de relatórios gerenciais financeiros estratégicos.&nbsp;</p><p>Atuar com gestão de time administrativo financeiro e seus processos, prazos e políticas.&nbsp;</p><p>Habilidades com ferramentas de informática,&nbsp; sistemas, planilhas, dashboards e indicadores.</p><p>Vivência em gestão de equipes, planejamento estratégico, senso crítico e analítico, comunicação e trabalho em time.&nbsp;</p><p>Disponibilidade para atuação 100% presencial, sendo diferencial residir em Olinda e região.&nbsp;</p><p>&nbsp;</p>', 'contabil', 'gerente', 'Ensino superior', NULL, 'efetivo', 'Período Integral', NULL, 'desabilitada', '23-gerente-administrativo-financeiro', '2024-09-10 09:26:51', '2024-11-21 15:43:13'),
(24, 'Estágio em Segurança do Trabalho', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de consultoria em Engenharia de segurança, medicina e saúde ocupacional, em Recife/ PE.</p><p><span style=\"font-size: 1rem;\">Para essa posição buscamos estudante do curso técnico de segurança do trabalho, a partir do 2º período e com disponibilidade mínima para 1 ano de estágio 6 h diárias.&nbsp;</span><br></p><p>Boa comunicação, organização, atenção, trabalho em equipe e proatividade.&nbsp;</p><p>Habilidade em ferramentas de informática, drives, plataformas e arquivos para gerenciamento de informações.&nbsp;</p><p>Estágio de aprendizado em atividades de docmentação e registros de programas de segurança, medicina e saúde ocupacional.&nbsp;</p><p>Atuação 100% presencial, na Boa Vista/ Recife.&nbsp;</p>', 'seguranca-trabalho', 'estagiario', 'Nível Técnico', NULL, 'estagio', NULL, NULL, 'desabilitada', '24-estagio-em-seguranca-do-trabalho', '2024-10-08 13:21:03', '2024-10-24 13:59:59'),
(25, 'Estágio Comercial', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de consultoria em Engenharia de segurança, medicina e saúde ocupacional, em Recife/ PE.</p><p><span style=\"font-size: 1rem;\">Para essa posição buscamos estudante do curso superior em Administração de empresas, marketing, processos gerenciais e afins com disponibilidade para 6 h diárias.&nbsp;</span><br></p><p>Habilidades de trabalhar em equipe, boa comunicação, organização, atenção e proatividade.&nbsp;</p><p>Habilidade em ferramentas de informática, drives, plataformas e arquivos para gerenciamento de informações.&nbsp;</p><p>Estágio de aprendizado em atividades de negociação, propostas e planejamento comercial.&nbsp;</p><p>Atuação 100% presencial, na Boa Vista/ Recife.&nbsp;</p>', 'comercial', 'estagiario', 'Ensino superior', NULL, 'estagio', NULL, NULL, 'desabilitada', '25-estagio-comercial', '2024-10-08 13:24:26', '2024-11-28 16:06:48'),
(26, 'Estágio em Direito', 'PE', 'Recife', '<p>Nosso cliente é uma empresa de consultoria&nbsp;<span style=\"font-size: 1rem;\">em Engenharia de segurança, medicina e saúde ocupacional, em Recife/ PE.</span></p><p><span style=\"font-size: 1rem;\">Para essa posição buscamos estudante do curso superior em Direito, a partir do 2º período e com disponibilidade de estágio 6 h diárias.&nbsp;</span><br></p><p>Boa comunicação, organização, atenção concentrada, trabalho em equipe e proatividade.&nbsp;</p><p>Habilidade em ferramentas de informática, drives, plataformas e recursos de inteligência artificial, será diferencial.&nbsp;&nbsp;</p><p>Estágio de aprendizado em atividades e rotinas de perícias trabalhistas.&nbsp;</p><p>Atuação 100% presencial, na Boa Vista/ Recife.&nbsp;</p>', 'juridica', 'estagiario', 'Ensino superior', NULL, 'estagio', NULL, NULL, 'desabilitada', '26-estagio-em-direito', '2024-10-09 14:29:30', '2024-10-25 15:15:03'),
(27, 'Vendedor Backoffice', 'PE', 'Recife', '<p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Nosso cliente é uma industria de soluções tecnológicas.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Para esse perfil é necessário profissional com vivência na área de VENDAS INTERNAS com foco no cliente b2b (empresas x empresas), metas,&nbsp; negociações, propostas e acompanhamento de clientes.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Habilidades com informática básica, preferencialmente CRM, indicadores de vendas e sistemas de gestão de vendas.</span></p><p></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Ensino superior cursando, em administração, gestão comercial, negócios ou afins.&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;;\">Habilidades de relacionamento, comunicação interpessoal e negociação são preferenciais.&nbsp;&nbsp;</span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\"><br></span></p><p><span style=\"font-family: &quot;Source Sans Pro&quot;; font-size: 1rem;\">Oferecemos salário compatível com mercado,&nbsp; variável, vale transporte e refeição no local, e ambiente de trabalho inovador.&nbsp;</span></p>', 'comercial', 'consultor', 'Ensino superior', NULL, 'efetivo', NULL, NULL, 'desabilitada', '27-vendedor-backoffice', '2024-11-13 11:12:58', '2025-04-04 08:28:37'),
(28, 'Coordenador de Turismo', 'PE', 'Recife', '<p>Nosso cliente é uma instituição no segmento de serviços que atua em todo estado de Pernambuco. Para esta posição, buscamos profissional com atuação 100% presencial, com perfil:&nbsp;</p><p><br></p><p>Missão: Planejar e coordenar as atividades contribuindo para melhorar as condições de serviços de turismo e hotelaria, oferecidos aos clientes nas unidades executivas, de acordo com as normas, projetos e programas da instituição.&nbsp;</p><p><span style=\"font-size: 1rem;\">Responsabilidades: </span></p><p><span style=\"font-size: 1rem;\">Planejar e coordenar atividades e projetos, contribuindo para ações de turismo e hotelaria, agenciando e promovendo viagens de lazer ou negócios, feiras, congressos e exposições.&nbsp;</span><span style=\"font-size: 1rem;\">Contribuir para promoções de vendas de passagens, reservs de hotéias e programações de passeios e excursões. Acompanhar relatórios de vendas de passagens, reservas de hotéis e programações de passeios e excursões. Acompanhar relatórios de vendas de passagens, reservas de hotéis e programações de passeios e excursões. Acompanhar relatórios de performance e desenvolvimento de negócios, frente ao desempenho das atividades do time e programas da instituição. Acompanhar orçamentos, comunicações e negociações com stakeholders, para contratação de serviços. Disponibilidade para viagens ocasinais em Pernambuco.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Graduação em Administração, Hotelaria, Turismo ou afins. Pós graduação será diferencial.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Experiência com gestão de times e projetos de hotelaria/ turismo, e vivência em controles e orçamentos, gestão por resultados.&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Habilidade com ferramentas de informática e metodologias ágeis,&nbsp;</span></p><p><span style=\"font-size: 1rem;\">Comunicação, relações interpessoais e política para atuar em times multidisciplinares e institucionais.&nbsp;</span></p>', 'administrativo', 'coordenador', 'Ensino superior', NULL, NULL, NULL, NULL, 'desabilitada', '28-coordenador-de-turismo', '2025-01-06 17:26:50', '2025-02-11 09:03:53'),
(29, 'Auxiliar Administrativo', 'PE', 'Recife', '<p>Nosso cliente é uma indústria de alimentos: cremes e sorvetes.&nbsp;</p><p>Para essa posição buscamos profissional com formação a partir do ensino médio completo.&nbsp;</p><p>Necessário habilidade com pacote office básico e ferramentas de informática.&nbsp;</p><p>Habilidades comportamentais como disposição ao aprendizado, atenção concentrada, organização , iniciativas para o trabalho em equipe será diferencial.&nbsp;</p><p>Experiências com rotinas administrativas, controles, atualização de dados em sistemas, vendas e atendimento a cliente será preferencial.&nbsp;</p><p>Atuação 100% presencial no bairro da IMBIRIBEIRA, salário e benefícios compatíveis com mercado.&nbsp;</p>', 'administrativo', 'auxiliar', 'Ensino médio (2º grau)', NULL, 'efetivo', 'Período Integral', NULL, 'desabilitada', '29-auxiliar-administrativo', '2025-04-04 08:32:54', '2025-05-12 15:50:07');
